if ($idlePressureTest -notmatch 'advance' -or $idlePressureTest -notmatch 'morale' -or $idlePressureTest -notmatch 'foodInventory' -or $idlePressureTest -notmatch 'FixtureUnchanged' -or $idlePressureTest -notmatch 'party-shrunk') { throw 'IdlePressure must let the Native clock run, sample party food/morale/members, and stop when the party shrinks.' }
if ($idlePressureTest -notmatch 'TopUpFoodUnits' -or $idlePressureTest -notmatch 'isFood' -or $idlePressureTest -notmatch 'tradeConfirm' -or $idlePressureTest -notmatch 'TopUpBoughtFood') { throw 'IdlePressure must be able to stock the larder through the native market before idling, so a starved run and a fed run can be compared.' }
if ($idlePressureTest -notmatch 'ShelterInTown' -or $idlePressureTest -notmatch 'town_wait' -or $idlePressureTest -notmatch "wait_leave" -or $idlePressureTest -notmatch 'ShelteredPartyNotEncountered') { throw 'IdlePressure must be able to idle inside a settlement, so a sheltered window proves whether the wounds came from starvation or from a map encounter.' }
if ($idlePressureTest -notmatch 'heroHitPoints' -or $idlePressureTest -notmatch 'ShelteredPartyNotBesieged' -or $idlePressureTest -notmatch 'shelter-besieged') { throw 'IdlePressure must record the hero hit points it is starving down and must name a siege that interrupts the shelter window, so a wound can be traced to a cause instead of assumed.' }
$scenarioVerdictSource = Get-Content (Join-Path $stageRoot 'Get-ScenarioVerdict.ps1') -Raw -Encoding UTF8
if ($scenarioVerdictSource -notmatch 'provider-decision' -or $scenarioVerdictSource -notmatch 'objective-subflow-result' -or $scenarioVerdictSource -notmatch 'goalClassification' -or $scenarioVerdictSource -notmatch 'observeAgain' -or $scenarioVerdictSource -notmatch 'campaign-time-monotonic' -or $scenarioVerdictSource -notmatch 'party-survived' -or $scenarioVerdictSource -notmatch 'every-decision-ended-in-action-control-or-classification' -or $scenarioVerdictSource -notmatch 'run-reached-a-terminal-outcome' -or $scenarioVerdictSource -notmatch 'subflowWindowRegressions' -or $scenarioVerdictSource -notmatch 'ScenarioVerdict\.json') { throw 'Get-ScenarioVerdict must read a live-model run back into the five scenario checks, normalise every decision shape the loops actually emit, and judge Campaign time per series instead of across subflow windows.' }
