if ($openingScenarioTest -notmatch 'Repeats' -or $openingScenarioTest -notmatch 'Get-ForkKind' -or $openingScenarioTest -notmatch 'ConversationForksCarryNativeOptions' -or $openingScenarioTest -notmatch 'EveryRepeatStoppedItsProcess' -or $openingScenarioTest -notmatch 'OpeningScenarioProgress') { throw 'OpeningScenario must replay the first decision of a checkpoint several times and judge the fork instead of a single run, so a scenario whose fork the world decides is measured rather than assumed.' }
